-- Tank rework v3 (Q approved 2026-10-28, thread "Brainstorm Tank rework v3"; design/tank-rework-v3-*.md).
-- Needs the engine from the same PR. NOT applied yet: back up the TK cards + TK style params first, check the
-- card rows against the live DB (the card list below came from the 26 Oct dossier snapshot), then apply after merge.
--
-- 1) S cards can cost a % of current HP (Tank pays HP): cards.cost_pct, on top of cards.cost (flat). Admin: Deck "Cost %".
alter table public.cards add column if not exists cost_pct integer check (cost_pct is null or (cost_pct >= 0 and cost_pct <= 100));

-- 2) Lifeline / Titan Bloom are new passives: their old numbers mean other things now, so the Style params go back to the
--    code defaults (engine/tuning.ts TK:1 / TK:2, Ascendancy nodes in engine/loadoutData.ts). Q tunes them again in Admin.
update public.champion_styles set params = '{}'::jsonb, effect = $t$Getting hurt fills ⛨ Endurance (max {endMax}). Strike to collect it all: heal and hit harder. Full without Striking: counter-spin.$t$, updated_at = now()
where champion_id = 'TK' and slot = 1;
update public.champion_styles set params = '{}'::jsonb, effect = $t$Growth (Max HP only): +{perHitTaken} per hit taken, +{perHitBlocked} per hit you Block, +{perDebuff} per debuff stack at the end of the turn. Meat (Max HP and HP): +{perFacing} per facing pair, +{meatPct}% of your Max HP per clean hit you land. Cap {maxHpCap}. Every {hpPerDmg} Max HP grown = every card +1 dmg. Above +{treeAt} grown you hold the tree: every card +{treeDmg} dmg, Field max {treeField}. A Strike of {throwCards}+ cards while holding it throws it: every card +{throwDmg} dmg instead, lose {throwCost} grown Max HP. Card heals give you only {cardHealPct}%.$t$, updated_at = now()
where champion_id = 'TK' and slot = 2;

-- 3) Deck v3.1: no flat heals, every heal halved; 4 defence P/K out, 4 Blood Price S cards in (P8 / K8 / S9);
--    S costs are a % of current HP (Blood Price 15%, Meditation 50%, Taunt 10%, the rest 5%).
update public.cards set dmg = 14, cost_pct = null, effect = $t$Comes into play, if this card was drawn into slot 1: Gain 2% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":1}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-001';
update public.cards set dmg = 16, cost_pct = null, effect = $t$Comes into play, if this card was drawn into slot 2: Gain 2% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":2}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-002';
update public.cards set dmg = 14, cost_pct = null, effect = $t$Comes into play, if this card was drawn into slot 3: Gain 2% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":3}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-003';
update public.cards set dmg = 10, cost_pct = null, effect = $t$Every turn (Hold), if you play Charge and opponent plays Strike: Gain 2% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onHeld","if":[{"c":"selfAction","a":"charge"},{"c":"enemyAction","a":"strike"}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-004';
update public.cards set dmg = 13, cost_pct = null, effect = $t$Before action, if you play Strike and you have Shield: This card +10 dmg$t$, effect_json = $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hasStatus","who":"self","kind":"shield"}],"do":[{"a":"addDmg","target":"this","n":10}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-006';
update public.cards set dmg = 10, cost_pct = null, effect = $t$Before action, if you play Block and opponent plays Strike: Gain Parry 1 next turn (the first 1 hit past Block are parried: 0 dmg)$t$, effect_json = $t$[{"hook":"modify","if":[{"c":"selfAction","a":"block"},{"c":"enemyAction","a":"strike"}],"do":[{"a":"status","who":"self","kind":"parry","turns":1,"n":1}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-007';
update public.cards set dmg = 10, cost_pct = null, effect = $t$After action, if you play Strike: Gain Shield 10 (absorbs hit dmg, lasts through next turn)$t$, effect_json = $t$[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"status","who":"self","kind":"shield","turns":1,"n":10}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-008';
update public.cards set dmg = 12, cost_pct = null, effect = $t$Before action, if you play Strike and opponent's HP < 50%: This card +8 dmg$t$, effect_json = $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hp","who":"enemy","op":"<","n":50,"pct":true}],"do":[{"a":"addDmg","target":"this","n":8}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-009';
update public.cards set dmg = 18, cost_pct = null, effect = $t$Comes into play: Gain 1.5% of your Max HP as HP / Before action, if you play Strike and your chain has 2+ Punch: This card +6 dmg$t$, effect_json = $t$[{"hook":"onDraw","do":[{"a":"heal","who":"self","n":1.5,"per":"maxHpPct"}]},{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"chainHas","who":"self","type":"P","n":2}],"do":[{"a":"addDmg","target":"this","n":6}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-010';
update public.cards set dmg = 10, cost_pct = null, effect = $t$Comes into play, if this card was drawn into slot 4: Gain 2% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":4}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-011';
update public.cards set dmg = 10, cost_pct = null, effect = $t$Comes into play, if this card was drawn into slot 5: Gain 2% of your Max HP as HP / Before action, if you play Charge and opponent plays Strike: Gain Parry 1 next turn (the first 1 hit past Block are parried: 0 dmg)$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":5}],"do":[{"a":"heal","who":"self","n":2,"per":"maxHpPct"}]},{"hook":"modify","if":[{"c":"selfAction","a":"charge"},{"c":"enemyAction","a":"strike"}],"do":[{"a":"status","who":"self","kind":"parry","turns":1,"n":1}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-012';
update public.cards set dmg = 8, cost_pct = null, effect = $t$Before action: All following cards (Kick only) +6 dmg$t$, effect_json = $t$[{"hook":"modify","do":[{"a":"addDmg","target":"following","n":6,"onlyType":"K"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-013';
update public.cards set dmg = 8, cost = null, cost_pct = 5, effect = $t$On hit, if your HP ≤ 29: Gain 5% of your missing HP as HP (once per game)$t$, effect_json = $t$[{"hook":"onHit","if":[{"c":"hpAtMost","n":29}],"do":[{"a":"heal","who":"self","n":5,"per":"missingHpPct"}],"once":true}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-014';
update public.cards set dmg = 8, cost = null, cost_pct = 5, effect = $t$Comes into play, if this card was drawn into slot 1 and there is a facing card: Gain 4% of your Max HP as HP$t$, effect_json = $t$[{"hook":"onDraw","if":[{"c":"enteredAt","n":1},{"c":"hasFacing"}],"do":[{"a":"heal","who":"self","n":4,"per":"maxHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-015';
update public.cards set dmg = 10, cost = null, cost_pct = 5, effect = $t$Comes into play: Your Block stops +1 hit next turn$t$, effect_json = $t$[{"hook":"onDraw","do":[{"a":"status","who":"self","kind":"blockPlus","turns":1,"n":1}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-016';
update public.cards set dmg = 10, cost_pct = null, effect = $t$After action, if you play Block: Opponent lose 3 HP per hit you blocked this turn$t$, effect_json = $t$[{"hook":"onResolve","if":[{"c":"selfAction","a":"block"}],"do":[{"a":"loseHp","who":"enemy","n":3,"per":"hitBlocked"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-019';
update public.cards set dmg = 12, cost = null, cost_pct = 10, in_deck = true, updated_at = now() where id = 'TK-020';
update public.cards set dmg = 10, cost_pct = null, effect = $t$On hit, if you've been hit by a Punch this turn: Gain 25% of your missing HP as HP$t$, effect_json = $t$[{"hook":"onHit","if":[{"c":"hitBy","n":1,"type":"P"}],"do":[{"a":"heal","who":"self","n":25,"per":"missingHpPct"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-022';
update public.cards set dmg = 9, cost_pct = null, in_deck = true, updated_at = now() where id = 'TK-023';
update public.cards set dmg = 9, cost_pct = null, effect = $t$Every turn (Hold), if you play Charge and you weren't hit this turn: Your next Strike: every chain card +3 dmg$t$, effect_json = $t$[{"hook":"onHeld","if":[{"c":"selfAction","a":"charge"},{"c":"notHit"}],"do":[{"a":"status","who":"self","kind":"empower","turns":9999,"n":3}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-026';
update public.cards set dmg = 1, cost = null, cost_pct = 50, effect = $t$Before action, if you play Strike: Gain 20% of your missing HP as HP, gain Shield 2 per 10 HP you are missing (absorbs hit dmg, lasts this turn only)$t$, effect_json = $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"heal","who":"self","n":20,"per":"missingHpPct"},{"a":"status","who":"self","kind":"shield","turns":0,"n":2,"per":"missingHp10"}]}]$t$::jsonb, in_deck = true, updated_at = now() where id = 'TK-027';
insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, cost_pct, style_only) values ('TK-028', 'TK', $t$Blood Price$t$, 'Q', 'Tank v3', 'S', 10, $t$Before action, if you play Strike: This card +0.5 dmg per HP this card cost (max +20), you regain 3% of missing HP at the end of every turn, 3 turns$t$, 1, 28, true, '{Attack,Technique}', $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"addDmg","target":"this","n":0.5,"per":"paidHp","max":20},{"a":"status","who":"self","kind":"regen","turns":3,"n":3}]}]$t$::jsonb, null, 15, null)
  on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = null, cost_pct = excluded.cost_pct, in_deck = true, updated_at = now();
insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, cost_pct, style_only) values ('TK-029', 'TK', $t$Crushing Weight$t$, 'Q', 'Tank v3', 'S', 12, $t$Before action, if you play Strike: This card ignores Block and Parry, you regain 3% of missing HP at the end of every turn, 3 turns$t$, 1, 29, true, '{Attack,Technique}', $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"pierce","target":"this","parry":true},{"a":"status","who":"self","kind":"regen","turns":3,"n":3}]}]$t$::jsonb, null, 15, null)
  on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = null, cost_pct = excluded.cost_pct, in_deck = true, updated_at = now();
insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, cost_pct, style_only) values ('TK-030', 'TK', $t$Last Rites$t$, 'Q', 'Tank v3', 'S', 12, $t$Before action, if you play Strike: You regain 3% of missing HP at the end of every turn, 3 turns / Before action, if you play Strike and opponent's HP < 30%: This card +15 dmg$t$, 1, 30, true, '{Attack,Technique}', $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"status","who":"self","kind":"regen","turns":3,"n":3}]},{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hp","who":"enemy","op":"<","n":30,"pct":true}],"do":[{"a":"addDmg","target":"this","n":15}]}]$t$::jsonb, null, 15, null)
  on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = null, cost_pct = excluded.cost_pct, in_deck = true, updated_at = now();
insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, cost_pct, style_only) values ('TK-031', 'TK', $t$Shatter Guard$t$, 'Q', 'Tank v3', 'S', 10, $t$Before action, if you play Strike: Remove the opponent's Shield and Parry first, this card +5 dmg per one removed, you regain 3% of missing HP at the end of every turn, 3 turns$t$, 1, 31, true, '{Attack,Technique}', $t$[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"shatter","n":5},{"a":"status","who":"self","kind":"regen","turns":3,"n":3}]}]$t$::jsonb, null, 15, null)
  on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = null, cost_pct = excluded.cost_pct, in_deck = true, updated_at = now();
-- out: TK-005 Spider Knee, TK-018 Stone Skin (the duplicate name), TK-021 Iron Palm, TK-025 Combo Breaker, and any other Tank card
-- not in the 25 above (TK-017 / TK-024 are already out of the deck in the live DB)
update public.cards set in_deck = false, updated_at = now()
where champion_id = 'TK' and in_deck and id not in ('TK-001', 'TK-002', 'TK-003', 'TK-004', 'TK-006', 'TK-007', 'TK-008', 'TK-009', 'TK-010', 'TK-011', 'TK-012', 'TK-013', 'TK-014', 'TK-015', 'TK-016', 'TK-019', 'TK-020', 'TK-022', 'TK-023', 'TK-026', 'TK-027', 'TK-028', 'TK-029', 'TK-030', 'TK-031');
